use xyg_engine::graphforge::{container::{Builder,DOCUMENT_MAGIC},interaction::{GraphSession,SessionLoad,Camera},compose::COMPOSITION_VERSION};
fn id(i:u8)->[u8;16]{[i;16]}
fn main(){
 let mut b=Builder::new(DOCUMENT_MAGIC);b.u32s("status",0,&[0]);b.utf8("kind",0,"graph");b.u32s("composition.version",0,&[COMPOSITION_VERSION]);b.uuids("node.uuid",0,&[id(1),id(2)]);b.uuids("edge.uuid",0,&[id(3)]);b.u8s("edge.derived",0,&[0]);b.u32s("edge.layer",0,&[u32::MAX]);b.i64s("edge.order",0,&[-1]);b.u64s("edge.path",0,&[u64::MAX]);b.u64s("edge.source",0,&[0]);b.u64s("edge.target",0,&[1]); b.u8s("edge.status",0,&[1]);let doc=b.finish();
 let mut s=GraphSession::create(&doc,SessionLoad{x:Some(vec![0.,100.]),y:Some(vec![0.,0.]),..Default::default()},7).unwrap(); let first=s.render(None).unwrap().clone(); let next=s.render(Some(Camera{scale_x:1e154,scale_y:1.,offset_x:0.,offset_y:0.,viewport_width:1e156,viewport_height:100.,dpr:1.}));println!("huge camera status {:?}",next.as_ref().err());let next=s.render(None).unwrap();println!("oldrev={} newrev={} oldpieces={} newpieces={} newnodes={:?}",first.revision,next.revision,first.paint.pieces.len(),next.paint.pieces.len(),next.paint.nodes.iter().map(|p|p.center).collect::<Vec<_>>()); for v in [100.,1e80,1e100,1e150,1e155]{let mut s=GraphSession::create(&doc,SessionLoad{x:Some(vec![0.,v]),y:Some(vec![0.,0.]),..Default::default()},7).unwrap();match s.render(None){Ok(r)=>println!("v={v}: nodecount={} edgecount={} pieces={} head={:?} mid_pick={:?}",r.node_count(),r.edge_count(),r.paint.pieces.len(),r.paint.pieces.first().map(|p|p.head),r.pick_at(v/2.,0.)),Err(e)=>println!("v={v}: error{e:?}")}}
}
